import json
from pathlib import Path

def build(config,out):
    data=json.dumps(config).replace('<','\\u003c')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stellar Forge — readiness v.1.2</title><style>body{font:16px system-ui;background:#111c2d;color:#e8effa;margin:0}main{max-width:1000px;padding:24px;margin:auto}section{background:#1d2d45;padding:18px;border-radius:12px;margin:16px 0}.banner{padding:14px;background:#49361c}input,select,button,textarea{font:inherit;padding:8px;border-radius:5px;max-width:100%;box-sizing:border-box}textarea{width:100%;height:280px;font:13px monospace}label{display:inline-block;margin:10px}pre{white-space:pre-wrap}button{cursor:pointer}#error{color:#ffbbb3}</style><main><h1>Stellar Forge readiness v.1.2</h1><p>Prepare until observed readiness — log every attempt</p><div class="banner">SIMULATION / OFFLINE OBSERVATION ANALYSIS. No sensor connection or laser-control interface. Readiness is a declared criterion, not proof of saturation or fusion improvement.</div><section><h2>Preparation policy</h2><label>Policy<select id="mode"><option value="UNTIL_READY">Prepare until ready</option><option value="FIXED_DURATION">Fixed duration — comparison</option></select></label><label>Confirmation window (s)<input id="hold" type="number" value="1" step="any"></label><label>Timeout (s)<input id="timeout" type="number" value="10" step="any"></label><label>Fixed duration (s)<input id="fixed" type="number" value="2" step="any"></label><p>Applies to every attempt in this batch. Edit specimen-specific criteria, sensor units, calibration IDs and observations in JSON. Values below are synthetic fixtures, not laboratory defaults.</p><button id="apply">Apply policy</button></section><section><h2>Attempt log input</h2><input id="load" type="file" accept=".json"><textarea id="config" aria-label="Complete readiness batch JSON"></textarea><button id="download">Download readiness configuration</button><p>Evaluate locally:</p><pre>stellar-forge-ready evaluate your_readiness.json --out runs/new_attempt_batch</pre><p id="error" role="alert"></p></section><section><h2>Inspect results</h2><input id="result" type="file" accept=".json"><pre id="summary">No observation evaluation loaded.</pre><p>INPUT.json and ATTEMPTS.jsonl preserve every supplied sample and specimen/calibration identity. SUMMARY.csv retains timeouts and aborts alongside successful preparations. No proposed trigger signal is sent.</p></section></main><script id="starter" type="application/json">__DATA__</script><script>
const $=id=>document.getElementById(id);$('config').value=JSON.stringify(JSON.parse($('starter').textContent),null,2);
function apply(){const c=JSON.parse($('config').value);for(const a of c.attempts){a.mode=$('mode').value;for(const [id,k] of [['hold','hold_s'],['timeout','timeout_s'],['fixed','fixed_duration_s']]){const v=Number($(id).value);if(!$(id).value.trim()||!Number.isFinite(v)||v<=0)throw Error('Positive '+id+' required');a[k]=v;}if(a.hold_s>a.timeout_s)throw Error('Confirmation window exceeds timeout');if(a.mode==='FIXED_DURATION'&&a.fixed_duration_s>a.timeout_s)throw Error('Fixed window exceeds timeout');}$('config').value=JSON.stringify(c,null,2);$('error').textContent='';return c;}
$('apply').onclick=()=>{try{apply();}catch(e){$('error').textContent=e.message;}};
$('download').onclick=()=>{try{const b=new Blob([JSON.stringify(apply(),null,2)+'\\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='stellar_readiness.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){$('error').textContent=e.message;}};
$('load').onchange=async e=>{try{const c=JSON.parse(await e.target.files[0].text());$('config').value=JSON.stringify(c,null,2);const a=c.attempts[0];$('mode').value=a.mode;$('hold').value=a.hold_s;$('timeout').value=a.timeout_s;$('fixed').value=a.fixed_duration_s||2;}catch(x){$('error').textContent=x.message;}};
$('result').onchange=async e=>{try{const r=JSON.parse(await e.target.files[0].text());$('summary').textContent=JSON.stringify(r,null,2);}catch(x){$('error').textContent=x.message;}};
</script></html>'''.replace('__DATA__',data)
    with Path(out).open('x') as f:f.write(html)
